// Phần bổ sung sau đối chiếu 240 trang PDF. Các ví dụ là minh họa tự tạo.
const L=(id,ch,title,pages,body,analogy,memory)=>({id,ch,title,pages,body,analogy,memory,questions:[]});
export const extraLessons=[
L('x1a',0,'Phân loại mạng và phương tiện truyền',[4,6],'LAN phủ khu vực cục bộ; MAN quy mô đô thị; WAN phủ diện rộng. Đây là phân loại theo phạm vi, khác với topology bus, ring, star, mesh. Guided media dẫn tín hiệu trong dây như cáp xoắn đôi, đồng trục, quang; unguided media truyền qua không gian như vô tuyến. File/print services chia sẻ tài nguyên; Telnet minh họa truy nhập từ xa trong bài giảng.','Đường trong một làng minh họa LAN; tuyến nối các làng xa nhau minh họa WAN. Hình đường và phạm vi quản lý là hai tiêu chí riêng.','Phạm vi ≠ topology; có dây ≠ không dây'),
L('x1b',0,'Các công nghệ mạng truy cập',[9,11],'DSL dùng đường dây điện thoại và DSLAM. Cable dùng mạng lai quang–đồng trục HFC với CMTS. FTTH đưa cáp quang tới nhà, dùng OLT/ONT. Ethernet và Wi‑Fi phục vụ truy cập gia đình/tổ chức; Wi‑Fi qua access point. Mạng di động 3G/LTE dùng trạm gốc trên phạm vi rộng. Các mức Mbps trong slide là ví dụ tại thời điểm biên soạn, không phải trần tốc độ mọi triển khai.','Đường bộ, đường trên không và đường chuyên dụng tới cổng làng minh họa các loại access network; chúng cùng nối host tới router biên.','DSL: điện thoại; HFC: quang + đồng trục; FTTH: quang tới nhà'),
L('x1c',0,'ISP, chuẩn và lịch sử Internet',[7,25],'Internet là mạng của các mạng: access ISP kết nối người dùng, các ISP nối nhau và kết nối mạng nhà cung cấp nội dung. IXP là điểm trao đổi lưu lượng giữa các mạng. IETF phát triển chuẩn Internet, nhiều đặc tả được công bố dưới dạng RFC. Dòng thời gian của tài liệu đi từ nghiên cứu chuyển mạch gói, ARPANET, TCP/IP năm 1983 tới Web, băng rộng, di động và điện toán đám mây.','Các làng có đường nội bộ riêng rồi liên minh tại điểm trao đổi thư: minh họa ISP/IXP; quy ước chung minh họa chuẩn liên mạng.','Internet = mạng của các mạng; IETF / RFC'),
L('x1d',0,'Luyện hiệu năng: hàng đợi và lưu lượng',[12,27],'Dùng nhất quán bit và giây: 1 byte=8 bit; 1 Mbps=10⁶ bit/s; 1 ms=10⁻³ s. Với gói cùng cỡ L, tốc độ đến a gói/s và đường truyền R bit/s, ρ=La/R. Nếu ρ lớn hơn 1 kéo dài, hàng đợi tăng tới khi có thể mất gói. Nếu còn một phần gói đang phát và n gói đang chờ, trễ chờ bằng phần truyền còn lại cộng nL/R. Store-and-forward qua N link đồng tốc cho một gói cần NL/R khi bỏ qua các trễ khác.','Kho cuộn thư còn một nửa kiện đang chuyển và bốn kiện chờ: thư mới phải đợi hết phần còn lại cộng bốn lượt chuyển.','ρ=La/R; d_queue=(L−x)/R+nL/R'),
L('x2a',1,'Đọc HTTP request và response',[30,36],'Request line chứa method, đường dẫn và phiên bản; Host cho biết máy chủ. Các header kết thúc bằng một dòng trống CRLF; phần body bắt đầu sau đó. Response có phiên bản, status code, reason phrase rồi header và body. Content-Length đo số byte của phần thân trong ví dụ. Date là lúc tạo phản hồi; Last-Modified là lần sửa tài nguyên, hai mốc này khác nhau. User-Agent mô tả phần mềm client, không phải địa chỉ IP nguồn.','Phiếu yêu cầu có tên dịch vụ, tên nơi nhận và nội dung riêng: minh họa cấu trúc bản tin HTTP, không phải mọi trường đều chứa địa chỉ mạng.','Request line / headers / dòng trống / body'),
L('x2b',1,'Thực hành quan sát và bộ đệm Web',[36,38],'Theo bài giảng: bắt gói bằng Wireshark, tạo một yêu cầu HTTP phù hợp, dừng capture rồi lọc các bản tin. Chỉ dùng lưu lượng bạn được phép quan sát. Với kết nối mã hóa, bộ lọc HTTP không tự làm lộ nội dung đã mã hóa. Cache hit: proxy có bản sao phù hợp và trả cho client; cache miss: phải lấy từ origin rồi có thể lưu bản sao. Cache giảm lưu lượng ra Internet khi tái sử dụng được đối tượng.','Kho thư gần ninja có sẵn bản sao phù hợp là cache hit; không có thì phải lấy từ trạm gốc là miss.','Hit: dùng cache; miss: hỏi origin'),
L('x2c',1,'FTP, SMTP: lệnh và trạng thái',[40,49],'FTP duy trì thư mục hiện tại và trạng thái xác thực. LIST lấy danh sách, RETR tải xuống, STOR tải lên; dữ liệu đi riêng với lệnh điều khiển. SMTP theo ví dụ cổ điển dùng văn bản ASCII 7 bit, ba giai đoạn bắt tay–truyền–đóng, kết thúc dữ liệu bằng CRLF.CRLF. Phân biệt mailbox chứa thư đã tới với hàng đợi thư đang chờ gửi. POP/IMAP lấy hoặc quản lý thư; SMTP chuyển thư giữa server.','Quầy nhiệm vụ nhớ ninja đã xác thực và đang đứng ở kho nào minh họa trạng thái FTP; danh sách thư chờ xe là hàng đợi SMTP.','FTP có trạng thái; SMTP chuyển thư; POP/IMAP truy cập thư'),
L('x3a',2,'Đọc header TCP và phân đoạn dữ liệu',[49,52],'MSS là lượng dữ liệu tối đa trong một TCP segment, không gồm header. TCP data offset dài 4 bit, tính header theo đơn vị 32 bit = 4 byte. Sequence/ACK dài 32 bit; source/destination port dài 16 bit. ACK flag xác nhận trường ACK có ý nghĩa; SYN/FIN phục vụ vòng đời kết nối; checksum phát hiện lỗi. Các chú thích PSH/URG trong slide là đơn giản hóa cho môn học.','Số byte nội dung trong cuộn thư là payload; tem và địa chỉ là header. MSS chỉ giới hạn phần nội dung chứ không đếm tem.','TCP header bytes = data offset × 4; MSS chỉ tính dữ liệu'),
L('x3b',2,'Cửa sổ trượt qua một tình huống',[36,46],'GBN xác nhận cộng dồn tới gói đúng thứ tự cao nhất; bên nhận bỏ gói đến ngoài thứ tự trong mô hình bài giảng. Khi timeout gói cũ nhất chưa ACK, gửi lại gói đó và các gói sau còn chờ. SR đệm gói đến ngoài thứ tự, ACK riêng từng gói, nhưng cửa sổ gửi chỉ trượt khi đã ACK liên tục từ đầu cửa sổ. Đúng riêng một gói phía sau không đủ để bỏ qua lỗ hổng phía trước.','Đội nhận có thể giữ cuộn số 3 và 4 trong kho SR nhưng chưa giao trọn nhiệm vụ nếu cuộn số 2 còn thiếu.','SR: đệm ngoài thứ tự; trượt qua đoạn ACK liên tục'),
L('x3c',2,'Tính rwnd và đọc đồ thị cwnd',[56,65],'Không gian nhận khả dụng rwnd bằng dung lượng bộ đệm trừ dữ liệu đang chiếm bộ đệm. Dữ liệu chưa ACK không được vượt min(rwnd,cwnd). Trong mô hình TCP cổ điển ở slide: khởi đầu 1 MSS, slow start tăng gấp đôi theo RTT tới ngưỡng; sau đó tăng tuyến tính. Timeout đặt ngưỡng khoảng một nửa cwnd và quay lại slow start. Xử lý ACK trùng tùy biến thể; không khái quát mọi TCP hiện đại theo hình này.','Kho người nhận còn chỗ không có nghĩa đường vận chuyển còn tải; ninja phải tôn trọng cả rwnd và cwnd.','rwnd = RcvBuffer − bytes đang đệm'),
L('x4a',3,'Phân lớp IPv4 và đọc mask',[10,21],'Theo mô hình phân lớp lịch sử, bit đầu quyết định A (0), B (10), C (110), D (1110 multicast), E (1111 dự phòng). A/B/C có mask mặc định /8, /16, /24; không dùng mask mặc định nếu đề đã cho CIDR. Dải 127/8 dành cho loopback, không gán như địa chỉ host thông thường. /20 tương ứng 255.255.240.0. Dùng AND với mask để tìm mạng; mọi bit host bằng 1 tạo broadcast trong subnet thông thường.','Tên nhóm quản lý cũ minh họa phân lớp; khi tờ nhiệm vụ đã ghi ranh giới prefix, phải dùng ranh giới đó.','Có CIDR thì dùng CIDR; 127/8 là loopback'),
L('x4b',3,'Trường IP, IPv6 và ý nghĩa độ dài',[44,55],'IHL IPv4 đo bằng từ 32 bit; total length gồm header và payload. TTL đếm số chặng còn lại, giảm khi qua router. Protocol nhận diện giao thức tầng trên; IPv4 checksum chỉ bảo vệ header. IPv6 header cơ bản 40 byte; payload length đo phần sau header cơ bản, next header chỉ phần tiếp theo (giao thức hoặc extension). Flow label nhóm luồng. Địa chỉ hex có thể bỏ số 0 đầu nhóm và nén một dãy nhóm 0 bằng :: một lần.','Tem tuyến đường IP có trường độ dài và số trạm còn được đi qua; không nhầm tuổi giấy với thời gian thực tế.','IPv4 total length có header; IPv6 payload length không có base header'),
L('x4c',3,'Bảng định tuyến và hệ tự quản',[58,81],'Bảng định tuyến chứa mạng đích/prefix, next hop hoặc interface ra và thông tin chi phí. Tuyến trực tiếp dùng interface nối mạng; tuyến gián tiếp gửi next hop. Định tuyến tĩnh cần quản trị viên sửa; động dùng giao thức cập nhật. Link-state biết sơ đồ/chi phí; DV nhận vector từ láng giềng và cập nhật Bellman–Ford. RIP, OSPF, IGRP là các ví dụ IGP; BGP trao đổi tuyến giữa các AS theo phạm vi giới thiệu của PDF.','Bảng giao liên ghi vùng đích và trạm kế tiếp; liên minh làng là minh họa tự tạo cho AS.','Đích/prefix → next hop/interface; D_x(y)=min_v[c(x,v)+D_v(y)]')
];
